<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Eye, Search, X } from 'lucide-vue-next'
import { adminApi, rows } from '@/api/services'
import { apiMessage } from '@/api/client'
import { dateTime, money } from '@/utils'
import type { Order, Payment } from '@/types'
import AdminPageHeader from '@/components/AdminPageHeader.vue'
import UiStatus from '@/components/UiStatus.vue'
const route=useRoute();const paymentMode=computed(()=>route.path.endsWith('payments'));const data=ref<(Order|Payment)[]>([]),query=ref(''),status=ref(''),error=ref(''),selected=ref<Order>(),detailError=ref('')
async function load(){try{const result:any=paymentMode.value?await adminApi.payments({q:query.value,status:status.value}):await adminApi.orders({q:query.value,status:status.value});data.value=rows<any>(result)}catch(e){error.value=apiMessage(e)}}
async function view(item:Order){detailError.value='';try{selected.value=await adminApi.order(item.order_no)}catch(e){detailError.value=apiMessage(e,'订单详情加载失败')}}
watch(paymentMode,load);onMounted(load)
</script>
<template><AdminPageHeader :title="paymentMode?'支付记录':'订单管理'" :description="paymentMode?'查看渠道交易与支付回调状态。':'查看余额订单、在线订单及发卡异常。'"/><div class="admin-toolbar"><label class="search-field"><Search/><input v-model="query" :placeholder="paymentMode?'搜索订单号或渠道流水':'搜索订单号、用户或商品'" @keyup.enter="load"/></label><select v-model="status" @change="load"><option value="">全部状态</option><template v-if="paymentMode"><option value="created">已创建</option><option value="success">支付成功</option><option value="failed">失败</option></template><template v-else><option value="pending_payment">待支付</option><option value="completed">已完成</option><option value="expired">已过期</option><option value="delivery_failed">发卡异常</option></template></select><button class="btn btn--secondary btn--sm" @click="load">查询</button></div><div v-if="error" class="alert alert--error">{{error}}</div><div class="data-panel"><div class="table-wrap"><table v-if="paymentMode"><thead><tr><th>订单号</th><th>支付通道</th><th>渠道流水</th><th>金额</th><th>状态</th><th>回调</th><th>创建时间</th></tr></thead><tbody><tr v-for="item in data as Payment[]" :key="item.id"><td><strong>{{item.order_no}}</strong></td><td>{{item.provider||'-'}}</td><td>{{item.provider_trade_no||'-'}}</td><td>{{money(item.amount)}}</td><td><UiStatus :value="item.status"/></td><td>{{item.callback_status||'-'}}</td><td>{{dateTime(item.created_at)}}</td></tr></tbody></table><table v-else><thead><tr><th>订单号 / 商品</th><th>买家</th><th>支付方式</th><th>金额</th><th>状态</th><th>创建时间</th><th></th></tr></thead><tbody><tr v-for="item in data as Order[]" :key="item.order_no"><td><strong>{{item.order_no}}</strong><small>{{item.product_name}} · {{item.sku_name}} × {{item.quantity}}</small></td><td>{{item.user?.username||item.contact_masked||'游客'}}</td><td>{{item.payment_method==='balance'?'余额':'在线支付'}}</td><td>{{money(item.total_amount)}}</td><td><UiStatus :value="item.status"/></td><td>{{dateTime(item.created_at)}}</td><td class="actions"><button class="icon-btn" :aria-label="`查看订单 ${item.order_no}`" @click="view(item)"><Eye/></button></td></tr></tbody></table></div><div v-if="!data.length" class="state">暂无记录</div></div><div v-if="selected" class="modal-backdrop" @click.self="selected=undefined"><section class="modal" role="dialog" aria-modal="true" :aria-label="`订单 ${selected.order_no}`"><div class="modal-head"><div><small>订单详情</small><h2>{{selected.order_no}}</h2></div><button class="icon-btn" aria-label="关闭订单详情" @click="selected=undefined"><X/></button></div><dl class="detail-list"><div><dt>商品</dt><dd>{{selected.product_name}} · {{selected.sku_name}} × {{selected.quantity}}</dd></div><div><dt>买家</dt><dd>{{selected.user?.username||selected.contact||selected.contact_masked||'游客'}}</dd></div><div><dt>支付方式</dt><dd>{{selected.payment_method==='balance'?'余额支付':'在线支付'}}</dd></div><div><dt>金额 / 状态</dt><dd>{{money(selected.total_amount)}} · <UiStatus :value="selected.status"/></dd></div></dl><div v-if="selected.cards?.length" class="delivered-cards"><h3>已发 CDK</h3><code v-for="card in selected.cards" :key="card">{{card}}</code></div><div v-else class="state">当前没有已发 CDK</div><div v-if="detailError" class="alert alert--error">{{detailError}}</div></section></div></template>
